window.docContents[98].resolve({"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Membership":{"contents":"def member (v : Nat) (l : NatList) : Bool := solution!(\n  match l with\n  | [] => false\n  | h :: t => bif v == h then true else member v t)\n\ntheorem member_nil {v : Nat} : member v [] = false := solution!(by rfl)\n\ntheorem member_cons_same {v₁ v₂ : Nat} {t : NatList} (h : (v₁ == v₂) = true) :\n    member v₁ (v₂ :: t) = true := by\n  solution!\n    dsimp [member]\n    rw [h, cond_true]\n\ntheorem member_cons_diff {v₁ v₂ : Nat} {t : NatList} (h : (v₁ == v₂) = false) :\n    member v₁ (v₂ :: t) = member v₁ t := by\n  solution!\n    dsimp [member]\n    rw [h, cond_false]\n\nexample : member 1 [1] = true := by\n  rw [member_cons_same rfl]\n\nexample : member 2 [1] = false := solution!(by rfl) -- rfl\n\ntheorem test_member1 : member 1 [1, 4, 1] = true := solution!(by rfl)\ntheorem test_member2 : member 2 [1, 4, 1] = false := solution!(by rfl)\n\n\n","context":"Logical Foundations\u0009Lists: Working with Structured Data\u0009Lists of Numbers","header":"5.2.5. Membership","id":"/Lists/#Logical-Foundations--Lists___-Working-with-Structured-Data--Lists-of-Numbers--Membership"}});